import java.util.*;

public class RoundRobin {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int quantum = sc.nextInt();

        Queue<Process> queue = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int time = sc.nextInt();
            queue.add(new Process(name, time));
        }

        int elapsed = 0;

        while (!queue.isEmpty()) {
            Process p = queue.poll();
            if (p.time <= quantum) {
                elapsed += p.time;
                System.out.println(p.name + " " + elapsed);
            } else {
                elapsed += quantum;
                p.time -= quantum;
                queue.add(p);
            }
        }

        sc.close();
    }

    static class Process {
        String name;
        int time;

        Process(String name, int time) {
            this.name = name;
            this.time = time;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Process {
        String name;
        int time;

        Process(String name, int time) {
            this.name = name;
            this.time = time;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int q = fs.nextInt();

        ArrayDeque<Process> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            String name = fs.next();
            int time = fs.nextInt();
            queue.addLast(new Process(name, time));
        }

        StringBuilder sb = new StringBuilder();
        int currentTime = 0;

        while (!queue.isEmpty()) {
            Process p = queue.pollFirst();
            if (p.time <= q) {
                currentTime += p.time;
                sb.append(p.name).append(' ').append(currentTime).append('\n');
            } else {
                currentTime += q;
                p.time -= q;
                queue.addLast(p);
            }
        }

        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

