    char name[NAME_LEN];
    int time;
} Process;

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2) return 0;

    Process queue[MAXN];
    for (int i = 0; i < n; i++) {
        scanf("%s %d", queue[i].name, &queue[i].time);
    }

    int head = 0, tail = n;
    int elapsed = 0;

    while (head < tail) {
        Process p = queue[head++];
        if (p.time <= q) {
            elapsed += p.time;
            printf("%s %d\n", p.name, elapsed);
        } else {
            elapsed += q;
            p.time -= q;
            queue[tail++] = p;
        }
    }

    return 0;
}

