from collections import deque

def solve():
    n, q = map(int, input().split())
    processes = deque()

    for _ in range(n):
        name, time = input().split()
        processes.append((name, int(time)))

    elapsed = 0
    while processes:
        name, time = processes.popleft()
        if time <= q:
            elapsed += time
            print(name, elapsed)
        else:
            elapsed += q
            processes.append((name, time - q))

if __name__ == "__main__":
    solve()
